function App() {
  const [currentScreen, setCurrentScreen] = useState<string>('ChannelThread');
  const [screenProps, setScreenProps] = useState<Record<string, any>>({});

  const navigate = (screen: string, props?: Record<string, any>) => {
    setScreenProps(props ?? {});
    setCurrentScreen(screen);
  };

  switch (currentScreen) {
    case 'ChannelThread':
      return <ChannelThread navigate={navigate} justShared={screenProps.justShared} />;
    case 'ShareToChat':
      return <ShareToChat navigate={navigate} />;
    default:
      return <ChannelThread navigate={navigate} />;
  }
}

