function ChannelThread({ navigate, justShared }: { navigate: (screen: string, props?: Record<string, any>) => void; justShared?: boolean }) {
  const sharedMessage = { id: 'm-shared', author: 'You', name: 'You', mine: true, text: 'Sharing this one \u2014 looks like a clean breakout.', ticker: INSTRUMENT };
  const [messages, setMessages] = useState(justShared ? [...INITIAL_MESSAGES, sharedMessage] : INITIAL_MESSAGES);
  const [inputText, setInputText] = useState('');

  const handleSend = () => {
    if (!inputText.trim()) return;
    setMessages([...messages, { id: 'm-' + messages.length, author: 'You', name: 'You', mine: true, text: inputText }]);
    setInputText('');
  };

  return (
    <div className="min-h-screen bg-white flex flex-col">
      {/* Header */}
      <div className="bg-white border-b border-grey-light-1 px-4 pt-12 pb-3">
        <div className="flex items-center gap-2">
          <div className="w-8 h-8 rounded-full bg-grey-light-2 flex items-center justify-center flex-shrink-0">
            <span className="text-xs font-semibold text-grey-dark">#</span>
          </div>
          <div className="flex-1">
            <p className="text-sm font-semibold text-neutral-900">emaar-watchers</p>
            <p className="text-xs text-grey-dark">{CHANNEL.memberCount} members</p>
          </div>
          <button onClick={() => navigate('ShareToChat')} className="border border-grey-light-1 rounded-full px-3 py-1.5">
            <span className="text-xs font-medium text-grey-dark">Share</span>
          </button>
        </div>
      </div>

      {/* Messages */}
      <div className="flex-1 overflow-y-auto px-4 py-4 space-y-3">
        {messages.map((msg: any) => (
          <div key={msg.id} className={`flex gap-2 ${msg.mine ? 'flex-row-reverse' : ''}`}>
            <div className="w-7 h-7 rounded-full bg-grey-light-2 flex items-center justify-center flex-shrink-0">
              <span className="text-xs font-medium text-grey-dark">{msg.author.slice(0, 2).toUpperCase()}</span>
            </div>
            <div className="max-w-[75%]">
              <p className="text-xs text-grey-dark mb-1">{msg.name}</p>
              <div className={`rounded-md px-3 py-2 ${msg.mine ? 'bg-neutral-900' : 'bg-grey-light-1'}`}>
                <p className={`text-sm ${msg.mine ? 'text-white' : 'text-neutral-900'}`}>{msg.text}</p>
              </div>
              {msg.ticker && (
                <div className="mt-2 border border-grey-light-1 rounded-md p-3 bg-white shadow-sm">
                  <div className="flex items-center justify-between gap-3">
                    <div>
                      <p className="text-sm font-semibold text-neutral-900">{msg.ticker.symbol}</p>
                      <p className="text-xs text-grey-dark">{msg.ticker.name}</p>
                    </div>
                    <div className="text-right">
                      <p className="text-sm font-semibold text-neutral-900">{msg.ticker.price}</p>
                      <p className="text-xs text-grey-dark">+{msg.ticker.changePercent}%</p>
                    </div>
                  </div>
                </div>
              )}
            </div>
          </div>
        ))}
      </div>

      {/* Compose */}
      <div className="bg-white border-t border-grey-light-1 px-4 py-3">
        <div className="flex items-center gap-2">
          <input
            type="text"
            value={inputText}
            onChange={(e) => setInputText(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleSend()}
            placeholder="Message #emaar-watchers"
            className="flex-1 bg-grey-light-1 rounded-full px-4 py-2 text-sm text-neutral-900 outline-none"
          />
          <button onClick={handleSend} className="w-9 h-9 rounded-full bg-neutral-900 flex items-center justify-center flex-shrink-0">
            <span className="text-white text-sm font-bold">\u2191</span>
          </button>
        </div>
      </div>
    </div>
  );
}

